    }
    TCHAR wintitle[256];
    lstrcpy_noaccel(wintitle, l10n->AdvancedTestWindow, ARR_SZ(wintitle));
    testwnd = CreateWindowEx(0
         , TEXT(APP_NAMEA)TEXT("-Test"), wintitle
