static xpure int IsSamePTT(const POINT *pt, const POINT *ptt)
{
    const short Tx = conf.dbclickX;
    const short Ty = conf.dbclickY;
    return !( pt->x > ptt->x+Tx || pt->y > ptt->y+Ty || pt->x < ptt->x-Tx || pt->y < ptt->y-Ty );
}

