static pure int XXButtonIndex(UCHAR vkey)
{
    WORD i;
    for (i=0; i < MAXKEYS && conf.XXButtons[i]; i++) {
        if(conf.XXButtons[i] == vkey)
            return i+3;
    }
    return -1;
}
