static void WriteCurrentLayoutNumber()
{
    if (MaxLayouts) {
        TCHAR txt[UINT_DIGITS+1];
        WritePrivateProfileString(TEXT("Zones"), TEXT("LayoutNumber"), Uint2lStr(txt, LayoutNumber), inipath);
